CREATE OR REPLACE VIEW `vwprovvanomale` AS select `p`.`id` AS `id`,`p`.`id_pratica` AS `id_pratica`,(select `ps`.`codice` from `pratica_stati` `ps` where `ps`.`id` = `k`.`pratica_stato_id`) AS `stato_pratica`,`p`.`data_status` AS `data_status`,`t`.`id_pratica` AS `pratica_corretta`,`t`.`status_pratica` AS `stato_corretto`,`p`.`tipo` AS `tipo`,`p`.`denominazione_riferimento` AS `denominazione_riferimento`,`p`.`descrizione` AS `descrizione` from ((`provvigioni` `p` join `tmpprovvigioni` `t` on((`p`.`id` = `t`.`id`))) left join `pratiches` `k` on((`k`.`id` = `p`.`pratica_id`))) where (`p`.`id_pratica` <> `t`.`id_pratica`) order by `p`.`id_pratica` desc
